def longest_increasing_run(lst):
    if not lst:
        return 0
    longest = 1
    current = 1
    for i in range(1, len(lst)):
        if lst[i] > lst[i - 1]:
            current += 1
        else:
            current = 1
        longest = max(longest, current)
    return longest

def longest_decreasing_run(lst):
    if not lst:
        return 0
    longest = 1
    current = 1
    for i in range(1, len(lst)):
        if lst[i] < lst[i - 1]:
            current += 1
        else:
            current = 1
        longest = max(longest, current)
    return longest

def first_index_ge(lst, target):
    for i, x in enumerate(lst):
        if x >= target:
            return i
    return -1

def last_index_le(lst, target):
    result = -1
    for i, x in enumerate(lst):
        if x <= target:
            result = i
    return result

def reverse_in_chunks(lst, k):
    result = []
    for i in range(0, len(lst), k):
        chunk = lst[i:i + k]
        result.extend(reversed(chunk))
    return result

def union_preserve_order(a, b):
    seen = set()
    result = []
    for x in list(a) + list(b):
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def symmetric_difference_preserve_order(a, b):
    set_a = set(a)
    set_b = set(b)
    result = []
    seen = set()
    for x in a:
        if x not in set_b and x not in seen:
            result.append(x)
            seen.add(x)
    seen = set()
    for x in b:
        if x not in set_a and x not in seen:
            result.append(x)
            seen.add(x)
    return result

def most_common_element(lst):
    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
    max_count = max(counts.values())
    candidates = [x for x, c in counts.items() if c == max_count]
    return min(candidates)

def top_k_elements(lst, k):
    if k <= 0:
        return []
    return sorted(lst, reverse=True)[:k]

def differences_from_first(lst):
    if not lst:
        return []
    first = lst[0]
    return [x - first for x in lst]

def count_descents(lst):
    count = 0
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            count += 1
    return count

def count_ascents(lst):
    count = 0
    for i in range(len(lst) - 1):
        if lst[i] < lst[i + 1]:
            count += 1
    return count
